     2	
     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    private const int DailyLimit = 200;
     6	    private const int FeeThreshold = 100;
     7	    private const int WithdrawalFee = 5;
     8	    private const int CassetteCapacity = 5;
     9	    private const int MaxNotesPerPass = 4;
    10	
    11	    private static readonly Denomination[] Denominations = [Denomination.Fifty, Denomination.Twenty, Denomination.Ten];
    12	
    13	    public AtmResult Execute(AccountState account, Operation operation)
    14	    {
    15	        ArgumentNullException.ThrowIfNull(operation);
    16	
    17	        return operation switch
    18	        {
    19	            Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    20	            Operation.Deposit deposit => Deposit(account, deposit.Notes),
    21	            _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}.", nameof(operation)),
    22	        };
    23	    }
    24	
    25	    private AtmResult Withdraw(AccountState account, int amount)
    26	    {
    27	        if (amount <= 0 || amount % 10 != 0)
    28	        {
    29	            return Refuse(AtmStatus.InvalidAmount, account);
    30	        }
    31	
    32	        if (account.WithdrawnToday + amount > DailyLimit)
    33	        {
    34	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    35	        }
    36	
    37	        var fee = amount > FeeThreshold ? WithdrawalFee : 0;
    38	        if (amount + fee > account.Balance)
    39	        {
    40	            return Refuse(AtmStatus.InsufficientFunds, account);
    41	        }
    42	
    43	        if (FewestNotes(amount, Available()) is not { } combination)
    44	        {
    45	            return Refuse(AtmStatus.CannotDispense, account);
    46	        }
    47	
    48	        var dispensed = NoteCounts.None;
    49	        foreach (var pass in Passes(combination))
    50	        {
    51	            if (!dispenser.Dispense(pass))
    52	            {
    53	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    54	            }
    55	
    56	            dispensed += pass;
    57	        }
    58	
    59	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    60	
    61	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    62	    }
    63	
    64	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    65	    {
    66	        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total == 0)
    67	        {
    68	            return Refuse(AtmStatus.InvalidAmount, account);
    69	        }
    70	
    71	        if (dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    72	        {
    73	            return Refuse(AtmStatus.CassetteJammed, account);
    74	        }
    75	
    76	        var after = dispenser.Stock + notes;
    77	        if (Denominations.Any(denomination => after.Of(denomination) > CassetteCapacity))
    78	        {
    79	            return Refuse(AtmStatus.CassetteFull, account);
    80	        }
    81	
    82	        if (!dispenser.Load(notes))
    83	        {
    84	            return Refuse(AtmStatus.DispenserFault, account);
    85	        }
    86	
    87	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, account with { Balance = account.Balance + notes.Value });
    88	    }
    89	
    90	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
    91	        new(status, NoteCounts.None, 0, account);
    92	
    93	    /// <summary>Les billets disponibles : le stock, sans la cassette bloquée.</summary>
    94	    private NoteCounts Available()
    95	    {
    96	        var stock = dispenser.Stock;
    97	        var jammed = dispenser.Jammed;
    98	
    99	        int Count(Denomination denomination) =>
   100	            denomination == jammed ? 0 : Math.Max(0, stock.Of(denomination));
   101	
   102	        return new NoteCounts(Count(Denomination.Fifty), Count(Denomination.Twenty), Count(Denomination.Ten));
   103	    }
   104	
   105	    /// <summary>La combinaison qui fait exactement <paramref name="amount"/> avec le moins de billets, ou <c>null</c>.</summary>
   106	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   107	    {
   108	        NoteCounts? best = null;
   109	        for (var fifties = Math.Min(available.Fifties, amount / 50); fifties >= 0; fifties--)
   110	        {
   111	            var afterFifties = amount - fifties * 50;
   112	            for (var twenties = Math.Min(available.Twenties, afterFifties / 20); twenties >= 0; twenties--)
   113	            {
   114	                var rest = afterFifties - twenties * 20;
   115	                var tens = rest / 10;
   116	                if (rest % 10 != 0 || tens > available.Tens)
   117	                {
   118	                    continue;
   119	                }
   120	
   121	                var candidate = new NoteCounts(fifties, twenties, tens);
   122	                if (best is not { } current || candidate.Total < current.Total)
   123	                {
   124	                    best = candidate;
   125	                }
   126	            }
   127	        }
   128	
   129	        return best;
   130	    }
   131	
   132	    /// <summary>Découpe la combinaison en passages d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
   133	    private static IEnumerable<NoteCounts> Passes(NoteCounts notes)
   134	    {
   135	        var remaining = notes;
   136	        while (remaining.Total > 0)
   137	        {
   138	            var room = MaxNotesPerPass;
   139	            var fifties = Math.Min(room, remaining.Fifties);
   140	            room -= fifties;
   141	            var twenties = Math.Min(room, remaining.Twenties);
   142	            room -= twenties;
   143	            var tens = Math.Min(room, remaining.Tens);
   144	
   145	            var pass = new NoteCounts(fifties, twenties, tens);
   146	            remaining -= pass;
   147	
   148	            yield return pass;
   149	        }
   150	    }
   151	}
namespace Atm;

public enum Denomination { Fifty = 50, Twenty = 20, Ten = 10 }

public enum AtmStatus
{
    Ok,
    InvalidAmount,
    DailyLimitExceeded,
    InsufficientFunds,
    CannotDispense,
    CassetteJammed,
    CassetteFull,
    DispenserFault,
}

public readonly record struct NoteCounts(int Fifties, int Twenties, int Tens)
{
    public static NoteCounts None => default;
    public int Total => Fifties + Twenties + Tens;
    public int Value => Fifties * 50 + Twenties * 20 + Tens * 10;

    public int Of(Denomination denomination) => denomination switch
    {
        Denomination.Fifty => Fifties,
        Denomination.Twenty => Twenties,
        _ => Tens,
    };

    public static NoteCounts operator +(NoteCounts a, NoteCounts b) =>
        new(a.Fifties + b.Fifties, a.Twenties + b.Twenties, a.Tens + b.Tens);

    public static NoteCounts operator -(NoteCounts a, NoteCounts b) =>
        new(a.Fifties - b.Fifties, a.Twenties - b.Twenties, a.Tens - b.Tens);
}

public readonly record struct AccountState(int Balance, int WithdrawnToday);

public abstract record Operation
{
    public sealed record Withdraw(int Amount) : Operation;

    public sealed record Deposit(NoteCounts Notes) : Operation;
}

public readonly record struct AtmResult(AtmStatus Status, NoteCounts Notes, int Fee, AccountState Account);

public interface IMoneyDispenser
{
    NoteCounts Stock { get; }

    Denomination? Jammed { get; }

    bool Dispense(NoteCounts notes);

    bool Load(NoteCounts notes);
}

public interface ICashMachine
{
    AtmResult Execute(AccountState account, Operation operation);
}
namespace Atm;

/// <summary>Le vrai module de billets, déterministe.</summary>
public sealed class MoneyDispenser(NoteCounts stock, Denomination? jammed = null) : IMoneyDispenser
{
    public const int MaxNotesPerPass = 4;
    public const int CassetteCapacity = 5;

    public NoteCounts Stock { get; private set; } = stock;

    public Denomination? Jammed { get; } = jammed;

    public bool Dispense(NoteCounts notes)
    {
        var enough = notes.Fifties <= Stock.Fifties && notes.Twenties <= Stock.Twenties && notes.Tens <= Stock.Tens;
        if (!IsValid(notes) || notes.Total > MaxNotesPerPass || !enough)
        {
            return false;
        }

        Stock -= notes;

        return true;
    }

    public bool Load(NoteCounts notes)
    {
        var after = Stock + notes;
        var fits = after.Fifties <= CassetteCapacity && after.Twenties <= CassetteCapacity && after.Tens <= CassetteCapacity;
        if (!IsValid(notes) || !fits)
        {
            return false;
        }

        Stock = after;

        return true;
    }

    private bool IsValid(NoteCounts notes) =>
        notes is { Fifties: >= 0, Twenties: >= 0, Tens: >= 0, Total: > 0 }
        && (Jammed is not { } cassette || notes.Of(cassette) == 0);
}

